import{_ as a,o,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Accessibilità Web UI: copertura automatica e checklist manuale","description":"","frontmatter":{},"headers":[],"relativePath":"qa/a11y-web.md","filePath":"qa/a11y-web.md"}'),n={name:"qa/a11y-web.md"};function r(c,e,l,s,d,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="accessibilita-web-ui-copertura-automatica-e-checklist-manuale" tabindex="-1">Accessibilità Web UI: copertura automatica e checklist manuale <a class="header-anchor" href="#accessibilita-web-ui-copertura-automatica-e-checklist-manuale" aria-label="Permalink to &quot;Accessibilità Web UI: copertura automatica e checklist manuale&quot;">​</a></h1><p>Obiettivo dichiarato: <strong>WCAG 2.1 livello AA</strong>. Questo documento <strong>non</strong> afferma la conformità: riporta ciò che è misurato in modo automatico, cosa resta da verificare a mano e i limiti noti.</p><h2 id="copertura-automatica-playwright-axe-core" tabindex="-1">Copertura automatica (Playwright + axe-core) <a class="header-anchor" href="#copertura-automatica-playwright-axe-core" aria-label="Permalink to &quot;Copertura automatica (Playwright + axe-core)&quot;">​</a></h2><p><code>yarn workspace @clarae/web e2e a11y</code> (file <code>web/e2e/a11y.spec.ts</code>, libreria <code>@axe-core/playwright</code> 4.10.2). Tag axe: <code>wcag2a, wcag2aa, wcag21a, wcag21aa</code>. Il test <strong>fallisce</strong> con violazioni di impatto <code>serious</code> o <code>critical</code>; quelle <code>moderate</code>/<code>minor</code> non bloccano ma il test non le nasconde: si vedono rilanciando axe a mano.</p><table tabindex="0"><thead><tr><th>Cosa</th><th>Dettaglio</th></tr></thead><tbody><tr><td>Rotte</td><td>usage, vaults, devices, shares, admin: storage, limits, users, dettaglio utente, groups, dettaglio gruppo, config, dettaglio config, audit, 404</td></tr><tr><td>Dialog aperti</td><td>ZIP vault condiviso, sblocco vault privato, revoca condivisione, creazione utente, revoca dispositivo, quota utente</td></tr><tr><td>Temi</td><td>chiaro <strong>e</strong> scuro (<code>localStorage</code> + <code>prefers-color-scheme</code>), con <code>prefers-reduced-motion: reduce</code></td></tr><tr><td>Reflow</td><td>a 320 px di larghezza nessuno scroll orizzontale della pagina su tutte le rotte (le tabelle scorrono nel proprio contenitore)</td></tr><tr><td>Lingua</td><td><code>&lt;html lang&gt;</code> è valorizzato e segue la lingua (anche test unitario)</td></tr><tr><td>Tastiera (<code>keyboard.spec.ts</code>)</td><td>&quot;Vai al contenuto&quot; come primo stop, navigazione con Tab/Invio, focus visibile, dialog con focus trap, <code>Esc</code> e ripristino del focus, modulo compilabile solo da tastiera, tabelle con didascalia e intestazioni, link di riga raggiungibili</td></tr></tbody></table><p><strong>Esito misurato (Chromium, axe 4.10.2):</strong> 0 violazioni <code>serious</code>/<code>critical</code> su 14 rotte × 2 temi e 6 dialog × 2 temi. Prima delle correzioni: 1 problema bloccante, non di axe ma del test di reflow — il testo nascosto delle intestazioni di tabella (<code>position:absolute</code>) usciva dal contenitore scorrevole e allargava la pagina a 320 px (259 px di overflow su <code>/vaults</code>); corretto rendendo <code>.nd-table-wrap</code> un blocco di contenimento (<code>position: relative</code>). I token di colore e il focus trap dei dialog erano già conformi alla misura. <strong>Palette di Clarae notanda (1.5, ADR-0052):</strong> i token <code>--nd-*</code> della console derivano ora dai <code>--brand-*</code> di <code>packages/ui/src/tokens.css</code>, e <code>packages/workbench/src/styles/tokens.contrast.test.ts</code> impone un contrasto di almeno 4,5:1 tra testo e superficie nei due temi (testo e pulsanti pieni usano la tonalità scura del Teal, il Teal vero solo per ciò che non è testo); la misura axe qui sopra è precedente al cambio di palette e non è stata rifatta in questo passo.</p><p>Cosa axe <strong>non</strong> può dire (resta nella checklist manuale): ordine di lettura sensato, qualità delle etichette, adeguatezza dei testi alternativi, comprensibilità dei messaggi di errore, annunci dinamici reali, comportamento con zoom al 200 % in un browser reale, dimensione dei bersagli (2.5.8 è WCAG 2.2, non 2.1).</p><h2 id="cosa-resta-limiti-noti" tabindex="-1">Cosa resta / limiti noti <a class="header-anchor" href="#cosa-resta-limiti-noti" aria-label="Permalink to &quot;Cosa resta / limiti noti&quot;">​</a></h2><ul><li>I controlli sono su Chromium con API simulate (<code>page.route</code>): non sostituiscono la prova con dati reali e altri browser.</li><li>Il grafico di tendenza (admin → Archiviazione) è un SVG: verificare a mano che esista l&#39;alternativa testuale (tabella o descrizione) per gli utenti di screen reader.</li><li>Nessuna verifica con screen reader reale è stata eseguita in questo ciclo.</li></ul><h2 id="checklist-manuale-screen-reader-—-da-eseguire-prima-del-rilascio" tabindex="-1">Checklist manuale (screen reader) — da eseguire prima del rilascio <a class="header-anchor" href="#checklist-manuale-screen-reader-—-da-eseguire-prima-del-rilascio" aria-label="Permalink to &quot;Checklist manuale (screen reader) — da eseguire prima del rilascio&quot;">​</a></h2><p>Ambienti: macOS + Safari + <strong>VoiceOver</strong>; Windows + Firefox/Chrome + <strong>NVDA</strong>. Per ciascuno annotare versione e data.</p><ul><li>[ ] Al caricamento ogni pagina annuncia un titolo di documento sensato e il <code>h1</code> della pagina.</li><li>[ ] Il link &quot;Vai al contenuto&quot; è annunciato e porta al contenuto principale.</li><li>[ ] I landmark (header, nav &quot;principale&quot;, nav &quot;Sezioni di amministrazione&quot;, main) sono elencati e nominati.</li><li>[ ] La navigazione principale e quella admin annunciano la pagina corrente (<code>aria-current</code>).</li><li>[ ] Le tabelle: didascalia letta, intestazioni di colonna associate alle celle, intestazioni di riga (<code>th scope=row</code>).</li><li>[ ] Barra di utilizzo: annuncia nome, valore e massimo; il livello (ok/attenzione/critico) è comprensibile senza il colore.</li><li>[ ] Dialog: all&#39;apertura il titolo è annunciato e il focus è dentro; <code>Esc</code> chiude e il focus torna al pulsante che l&#39;aveva aperto.</li><li>[ ] Moduli (creazione utente, quota, limiti, config): ogni campo ha etichetta; un errore di validazione è annunciato e associato al campo (<code>aria-describedby</code>/<code>aria-invalid</code>).</li><li>[ ] Notifiche (toast &quot;Utente creato&quot;, &quot;Invito accettato…&quot;) sono annunciate senza spostare il focus.</li><li>[ ] Esportazione ZIP: lo stato &quot;in coda / in preparazione / pronto&quot; è annunciato; la richiesta di passphrase è comprensibile.</li><li>[ ] Cambio lingua e tema: il controllo è etichettato; dopo il cambio <code>lang</code> e l&#39;annuncio sono coerenti.</li><li>[ ] Zoom al 200 % e finestra stretta (320 px): nessuna perdita di contenuto o funzione.</li><li>[ ] Sistema in modalità contrasto elevato/colori forzati: testi, bordi e focus restano visibili.</li><li>[ ] Con &quot;riduci movimento&quot; attivo non restano animazioni.</li></ul>',12)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
